87	                          const LlmTokenSampleConfig& cfg) {
88	    const int vocab_size = cfg.vocab_size > 0 ? cfg.vocab_size : logits.w;
89	    std::vector<float> scores(vocab_size);
90	    std::memcpy(scores.data(), logits.data, sizeof(float) * vocab_size);
91	
92	    for (int t : history) {
93	        if (t < 0 || t >= vocab_size) continue;
94	        if (scores[t] < 0) {
95	            scores[t] *= cfg.repetition_penalty;
96	        } else {
97	            scores[t] /= cfg.repetition_penalty;
98	        }
99	    }
100	
101	    if (cfg.do_sample != 1 || cfg.temperature <= 0.0f) {
102	        return (int)(std::max_element(scores.begin(), scores.end()) - scores.begin());
103	    }
104	
105	    softmax_vec(scores, cfg.temperature);
106	    if (cfg.top_k > 0) apply_top_k(scores, cfg.top_k);
107	    if (cfg.top_p < 1.0f) apply_top_p(scores, cfg.top_p);
108	
109	    const float sum = std::accumulate(scores.begin(), scores.end(), 0.0f);
110	    if (!std::isfinite(sum) || sum <= 0.0f) {
111	        return (int)(std::max_element(scores.begin(), scores.end()) - scores.begin());
112	    }
113	
114	    return sample_from_probs(scores);
115	}
